CA = 'Clinical application'
CARDS = {
'np': [
(0, 'Definition', 'Define the puerperium.', 'The period from delivery of the placenta until the genital organs return to the non-pregnant state, about 6 weeks (42 days).', 1),
(1, 'Involution', 'Where is the uterine fundus immediately after delivery?', 'It is firm and contracted, at about the level of the umbilicus.', 1),
(2, 'Involution', 'How fast does the fundal height fall after delivery?', 'By about 1 cm (one finger breadth) per day.', 1),
(3, 'Involution', 'When is the uterus no longer palpable abdominally?', 'By day 10–14.', 1),
(4, 'Involution', 'What is the weight of the uterus after delivery, at 1 week and at 6 weeks?', 'About 1000 g after delivery, 500 g at 1 week and 60–100 g at 6 weeks.', 2),
(5, 'Involution', 'How do the uterine muscle cells involute?', 'The cells become smaller by autolysis; their number does not decrease.', 2),
(6, 'Involution', 'What stops bleeding from the placental site?', 'Contraction of the crossing myometrial fibres, which compress the vessels (living ligatures).', 2),
(7, 'Endometrium', 'From which layer does the endometrium regenerate?', 'From the basal layer of the decidua, by about day 10; the placental site is healed by 6 weeks.', 2),
(8, 'Cervix', 'How does the cervix close after delivery?', 'It admits 2–3 fingers for 4–6 days and 1 finger by day 10–14; the external os becomes a transverse slit.', 2),
(9, 'Lochia', 'What is the timing of lochia rubra, serosa and alba?', 'Lochia rubra on days 1–4, lochia serosa on days 5–9, and lochia alba from day 10 to 3–6 weeks.', 1),
(10, 'Lochia', 'What does offensive lochia with a tender, bulky uterus suggest?', 'Endometritis.', 1),
(11, 'Lochia', 'What does a return of red lochia on day 12 with a bulky uterus suggest?', 'Retained placental tissue or subinvolution; an ultrasound scan is indicated.', 3),
(12, 'Circulation', 'Why may heart disease decompensate immediately after delivery?', 'Autotransfusion from the contracting uterus increases cardiac output.', 3),
(13, 'Haematological', 'Is a white cell count of 20 × 10⁹/L on day 1 abnormal?', 'No. A count of up to 20–25 × 10⁹/L is normal in the first days if the woman is well.', 2),
(14, 'Haematological', 'How long does the hypercoagulable state last after delivery?', 'About 6 weeks; this is the period of highest risk of venous thromboembolism.', 2),
(15, 'Endocrine', 'When do hPL and hCG become undetectable after delivery?', 'By about day 10.', 1),
(16, 'Fertility', 'When is the earliest ovulation in a mother who is not breastfeeding?', 'At about day 25; contraception is therefore needed from day 21.', 2),
(17, 'Lactation', 'Which hormone produces milk and which hormone ejects it?', 'Prolactin (anterior pituitary) produces milk; oxytocin (posterior pituitary) causes milk ejection (let-down).', 1),
(18, 'Lactation', 'Why does breastfeeding speed uterine involution?', 'Suckling releases oxytocin, which contracts the uterus (after-pains).', 2),
(19, 'Lactation', 'What allows milk to "come in" on days 2–4?', 'The fall in oestrogen and progesterone after delivery of the placenta.', 2),
(20, 'Postnatal care', 'How many postnatal contacts does WHO recommend?', 'At least four: within the first 24 hours, on day 2–3, on day 7–14 and at 6 weeks.', 1),
(21, 'Postnatal care', 'Who receives anti-D after delivery, at what dose and by when?', 'An RhD-negative, non-sensitised mother of an RhD-positive baby: 500 IU IM within 72 hours, with a Kleihauer test.', 2),
(22, 'Postnatal care', 'How is a breastfeeding mother who is not immune to rubella managed?', 'MMR vaccine is given before discharge; breastfeeding may continue; pregnancy is avoided for 1 month.', 2),
(23, 'Breastfeeding', 'What are the WHO recommendations on breastfeeding?', 'Start within 1 hour of birth, breastfeed exclusively for 6 months and on demand, and continue up to 2 years.', 1),
(24, 'Breastfeeding', 'Which condition in the baby is an absolute contraindication to breastfeeding?', 'Galactosaemia.', 1),
(25, 'Breastfeeding', 'What feeding advice is given to an HIV-positive mother in Sudan?', 'Exclusive breastfeeding for 6 months while on antiretroviral therapy; mixed feeding is avoided.', 2),
(26, 'Breast', 'What is the commonest organism in mastitis, and how is it treated?', 'Staphylococcus aureus; flucloxacillin 500 mg 6-hourly for 10–14 days, and breastfeeding continues.', 2),
(27, 'Breast', 'On day 3 both breasts are hard and tender and the temperature is 37.8 °C. What is the diagnosis?', 'Breast engorgement; it is managed with frequent feeds, expression of milk and analgesia.', 2),
(28, 'Lactation', 'Which drug is used to suppress lactation after a stillbirth?', 'Cabergoline 1 mg as a single dose; it is avoided in pre-eclampsia or hypertension.', 2),
(29, 'Contraception', 'What are the three conditions of the lactational amenorrhoea method (LAM)?', 'No menstruation, full or nearly full breastfeeding, and a baby under 6 months; it gives 98% protection.', 2),
(30, 'Contraception', 'When can a copper IUD be inserted after delivery?', 'Within 48 hours or from 4 weeks; the period in between is avoided because of expulsion and perforation.', 3),
(31, 'Contraception', 'When can the combined oral contraceptive pill be started after delivery?', 'Not breastfeeding: from day 21 (day 42 if there is a risk of VTE). Breastfeeding: avoided until 6 months.', 3),
],
'ps': [
(0, 'Definition', 'Define puerperal pyrexia.', 'A temperature of 38 °C or more in the first 14 days after delivery.', 1),
(1, 'Definition', 'What is the classic definition of puerperal morbidity?', 'A temperature of 38 °C or more on any 2 of the first 10 days, excluding the first 24 hours.', 2),
(2, 'Definition', 'What is the WHO definition of puerperal sepsis?', 'Infection of the genital tract between rupture of membranes or labour and day 42, with two or more of: pelvic pain, fever, abnormal or offensive discharge, and delayed involution.', 3),
(3, 'Burden', 'What is the leading cause of maternal death in Sudan?', 'Sepsis.', 1),
(4, 'Causes', 'What is the commonest cause of puerperal infection?', 'Endometritis (infection of the upper genital tract).', 1),
(5, 'Causes', 'What causes fever with chest crackles on day 1 after caesarean section under general anaesthesia?', 'Atelectasis or aspiration (Mendelson syndrome).', 3),
(6, 'Causes', 'Which cause of puerperal fever typically begins 1–4 weeks after delivery?', 'Mastitis or breast abscess.', 2),
(7, 'Risk factors', 'What is the strongest risk factor for endometritis?', 'Caesarean section, especially in labour and without prophylactic antibiotics.', 1),
(8, 'Risk factors', 'What are the intrapartum risk factors for puerperal sepsis?', 'Prolonged labour, prolonged rupture of membranes, repeated vaginal examinations, instrumental delivery, tears, manual removal of the placenta and chorioamnionitis.', 2),
(9, 'Risk factors', 'Does precipitate labour increase the risk of infection?', 'No; prolonged labour does.', 2),
(10, 'Organisms', 'What is the commonest organism in puerperal endometritis?', 'Anaerobic streptococcus; the infection is usually polymicrobial.', 2),
(11, 'Organisms', 'Which organism causes most deaths from sudden puerperal sepsis?', 'Group A β-haemolytic streptococcus (Streptococcus pyogenes), often acquired from a family member with a sore throat.', 2),
(12, 'Organisms', 'Which organisms cause postpartum urinary tract infection?', 'Escherichia coli, Proteus and Klebsiella.', 1),
(13, 'Clinical features', 'What are the signs of endometritis?', 'Fever, lower abdominal pain, offensive lochia and a tender, bulky, subinvoluted uterus.', 1),
(14, 'Clinical features', 'What are the warning features of group A streptococcal sepsis?', 'The woman appears well and then collapses; severe pain requiring opioids, diarrhoea and vomiting, a rash and hypothermia.', 3),
(15, 'Recognition', 'What are the obstetric qSOFA criteria?', 'Respiratory rate ≥ 25/min, systolic blood pressure < 90 mmHg and altered mental state; two or more indicate high risk.', 2),
(16, 'Recognition', 'What is the escalation rule of the MEOWS chart?', 'One red trigger or two yellow triggers require urgent medical review.', 2),
(17, 'Investigations', 'Which test is essential in every postpartum fever in Sudan?', 'A blood film or rapid diagnostic test for malaria.', 1),
(18, 'Investigations', 'Why are blood cultures taken before antibiotics?', 'To identify the organism and its sensitivity; however, antibiotics must never be delayed beyond 1 hour.', 2),
(19, 'Management', 'What are the components of the Sepsis Six?', 'Give oxygen, IV fluids and IV antibiotics; take blood cultures, measure lactate (and haemoglobin) and monitor urine output.', 2),
(20, 'Management', 'Within what time must the Sepsis Six be completed?', 'Within 1 hour of suspecting sepsis.', 1),
(21, 'Antibiotics', 'What is the first-line antibiotic regimen for endometritis in Sudan?', 'Ceftriaxone 1–2 g IV daily plus metronidazole 500 mg IV 8-hourly.', 2),
(22, 'Antibiotics', 'What is the alternative antibiotic regimen for endometritis?', 'Clindamycin 900 mg IV 8-hourly plus gentamicin 5 mg/kg IV daily.', 3),
(23, 'Antibiotics', 'Why is clindamycin added in group A streptococcal toxic shock?', 'It suppresses bacterial toxin production.', 3),
(24, 'Antibiotics', 'Which antibiotics are avoided during breastfeeding?', 'Tetracyclines and chloramphenicol.', 1),
(25, 'Management', 'A woman remains febrile on antibiotics at day 7, with a bulky uterus and an open os. What is the next step?', 'Ultrasound scan; retained products are evacuated after antibiotics have been started.', 3),
(26, 'Complications', 'After caesarean section a woman has a spiking fever despite antibiotics, appears well and has no collection. What is the diagnosis?', 'Septic pelvic (ovarian vein) thrombophlebitis; it is confirmed by CT or MRI, and therapeutic heparin is added.', 3),
(27, 'Complications', 'What do a swinging fever, diarrhoea, tenesmus and a pelvic mass indicate?', 'A pelvic abscess in the pouch of Douglas, which requires drainage.', 3),
(28, 'Complications', 'What are the long-term complications of pelvic sepsis?', 'Tubal blockage causing infertility or ectopic pregnancy, and chronic pelvic pain.', 2),
(29, 'Prevention', 'When is antibiotic prophylaxis given at caesarean section, and which antibiotic is used?', 'Before the skin incision: cefuroxime 1.5 g IV or cefazolin 2 g IV (clindamycin 900 mg if allergic).', 2),
(30, 'Prevention', 'Why is co-amoxiclav avoided before delivery?', 'It is associated with necrotising enterocolitis in the newborn.', 3),
(31, 'Prevention', 'What is the single most effective measure to prevent puerperal sepsis?', 'Hand washing before every examination and every change of pad.', 1),
],
'pmd': [
(0, 'Classification', 'What are the three postpartum mood disorders, in order of severity?', 'Baby blues (mild), postnatal depression (moderate) and puerperal psychosis (severe; an emergency).', 1),
(1, 'Incidence', 'How common is the baby blues?', 'It affects 50–80% of new mothers.', 1),
(2, 'Onset', 'When does the baby blues begin and peak?', 'It begins on day 3–10 after delivery and peaks on day 4–5.', 1),
(3, 'Course', 'How long does the baby blues last?', 'It resolves within 2 weeks; if it lasts longer, depression should be considered.', 2),
(4, 'Clinical features', 'What are the features of the baby blues?', 'Tearfulness, mood swings, irritability, anxiety and poor sleep; the mother still copes and cares for her baby.', 1),
(5, 'Management', 'How is the baby blues managed?', 'Explanation and reassurance, rest and family support, with review if it has not resolved by 2 weeks. Antidepressants are not needed.', 2),
(6, 'Aetiology', 'What is the hormonal trigger of postpartum mood change?', 'The sudden fall in oestrogen and progesterone after delivery of the placenta.', 2),
(7, 'Incidence', 'How common is postnatal depression?', 'It affects 10–15% of mothers and about 10% of new fathers.', 1),
(8, 'Onset', 'When does postnatal depression begin?', 'At any time in the first year, usually within 3 months of delivery.', 1),
(9, 'Risk factors', 'What are the main risk factors for postnatal depression?', 'Previous depression, depression in pregnancy, family history, young age, absence of a partner, poor support, stressful life events and severe baby blues.', 2),
(10, 'Clinical features', 'Six weeks after delivery a mother has no enjoyment, sleeps poorly even when the baby sleeps and feels she is a bad mother. What is the diagnosis?', 'Postnatal depression.', 2),
(11, 'Screening', 'Which tool is used to screen for postnatal depression?', 'The Edinburgh Postnatal Depression Scale (EPDS): 10 items, each scored 0–3, with a maximum of 30.', 1),
(12, 'Screening', 'Which EPDS score indicates probable depression?', 'A score of 13 or more, which requires a full assessment.', 2),
(13, 'Screening', 'The total EPDS score is low but question 10 is scored. What is the action?', 'Question 10 is the self-harm item, so the woman is assessed on the same day.', 3),
(14, 'Investigations', 'Which blood tests are done in suspected postnatal depression?', 'Haemoglobin and TSH, because anaemia and postpartum thyroiditis mimic depression.', 2),
(15, 'Effect on the infant', 'What is the effect of maternal depression on the infant?', 'Poor bonding, insecure attachment, poor growth, delayed milestones and later behavioural problems.', 2),
(16, 'Drug treatment', 'Which antidepressant is preferred during breastfeeding, and at what dose?', 'Sertraline 50 mg once daily, increased up to 200 mg; breastfeeding continues.', 2),
(17, 'Drug treatment', 'For how long is an SSRI continued after recovery?', 'For about 6 months.', 2),
(18, 'Drug treatment', 'Why is fluoxetine avoided when the mother is breastfeeding a newborn?', 'It has a long half-life and accumulates in the baby.', 3),
(19, 'Prognosis', 'What is the recurrence rate of postnatal depression after the next delivery?', 'About 25%; the lifetime risk of further depression is over 70%.', 2),
(20, 'Incidence', 'What is the incidence of puerperal psychosis?', '1–2 per 1000 births (about 1 in 500).', 1),
(21, 'Onset', 'When does puerperal psychosis begin?', 'Suddenly, mostly in the first 2 weeks and up to 4 weeks after delivery.', 1),
(22, 'Risk factors', 'What are the strongest risk factors for puerperal psychosis?', 'Previous puerperal psychosis, bipolar disorder, and a family history of bipolar disorder or puerperal psychosis.', 2),
(23, 'Clinical features', 'On day 5 a mother has not slept, is confused and believes her baby is evil. What is the diagnosis?', 'Puerperal psychosis, which is a psychiatric emergency.', 2),
(24, 'Differential diagnosis', 'What must be excluded before diagnosing puerperal psychosis?', 'Organic causes: sepsis, malaria, eclampsia, cerebral venous thrombosis, metabolic disturbance, and drugs or drug withdrawal.', 3),
(25, 'Management', 'What are the first steps in the management of puerperal psychosis?', 'The mother is never left alone with the baby; psychiatric review is arranged on the same day; she is admitted, ideally to a mother-and-baby unit.', 2),
(26, 'Management', 'What is the drug treatment of puerperal psychosis?', 'An antipsychotic (olanzapine or haloperidol) with or without a short course of a benzodiazepine; lithium for mania; ECT if severe.', 3),
(27, 'Risk', 'What are the life-threatening risks of puerperal psychosis?', 'Suicide (about 5%) and infanticide (up to 4%).', 2),
(28, 'Drug treatment', 'Can a mother who takes lithium breastfeed?', 'No. Lithium reaches high levels in breast milk, so the baby is bottle-fed.', 2),
(29, 'Prevention', 'How is puerperal psychosis prevented in a woman with bipolar disorder?', 'Valproate is changed before pregnancy, a shared plan is made with psychiatry, sleep is protected, and prophylaxis is started immediately after delivery.', 3),
(30, 'Prognosis', 'What is the recurrence rate of puerperal psychosis after the next delivery?', 'About 50%; most women recover fully from each episode.', 2),
(33, CA, 'Which single feature makes a postpartum mood disorder an emergency?', 'Psychotic features or thoughts of harm.', 2),
],
'mm': [
(0, 'Definitions', 'Define maternal death.', 'Death of a woman during pregnancy or within 42 days of its end, from a cause related to or aggravated by the pregnancy, and not from an accident.', 1),
(1, 'Definitions', 'Define direct maternal death.', 'Death from obstetric complications or their management, for example PPH, eclampsia, sepsis or VTE.', 1),
(2, 'Definitions', 'Define indirect maternal death.', 'Death from a pre-existing or new non-obstetric disease that is made worse by pregnancy, for example heart disease or malaria.', 1),
(3, 'Definitions', 'Define late maternal death.', 'A direct or indirect maternal death between 42 days and 1 year after the end of pregnancy.', 2),
(4, 'Definitions', 'What is a coincidental maternal death?', 'An accidental or incidental death (road accident, violence); it is not counted in the maternal mortality ratio.', 2),
(5, 'Definitions', 'Define pregnancy-related death.', 'Death during pregnancy or within 42 days of its end from any cause, including accidents.', 2),
(6, 'Measurement', 'What is the formula of the maternal mortality ratio?', 'Number of maternal deaths ÷ number of live births × 100 000.', 1),
(7, 'Measurement', 'What is the denominator of the maternal mortality rate?', 'Women aged 15–49 years (per 100 000 per year).', 2),
(8, 'Measurement', 'Define the lifetime risk of maternal death.', 'The probability that a 15-year-old girl will die of a maternal cause during her life; in Sudan it is about 1 in 91.', 2),
(9, 'Measurement', 'What is the sisterhood method?', 'A method of estimating maternal deaths by asking adults about the deaths of their sisters.', 2),
(10, 'Morbidity', 'Define a maternal near miss.', 'A woman who nearly died but survived a life-threatening complication during pregnancy, childbirth or within 42 days.', 1),
(11, 'Figures', 'What is the maternal mortality ratio of Sudan (WHO estimate, 2023)?', '256 per 100 000 live births.', 1),
(12, 'Figures', 'What are the global maternal mortality ratio and number of deaths (2023)?', '197 per 100 000 live births; about 260 000 deaths per year.', 2),
(13, 'Figures', 'What share of maternal deaths occurs in sub-Saharan Africa?', 'About 70%; its maternal mortality ratio was 448 per 100 000 in 2023.', 2),
(14, 'Figures', 'What is Sustainable Development Goal target 3.1?', 'A global maternal mortality ratio below 70 per 100 000 live births by 2030.', 1),
(15, 'Causes', 'What are the leading causes of maternal death in Sudan?', 'Puerperal (genital tract) sepsis, followed by haemorrhage, hypertensive disorders and VTE.', 1),
(16, 'Causes', 'What is the leading cause of maternal death worldwide?', 'Haemorrhage, which accounts for about a quarter of deaths.', 1),
(17, 'Causes', 'What is the leading direct cause of maternal death in the United Kingdom?', 'Venous thromboembolism.', 2),
(18, 'Causes', 'Which organism causes fatal community-acquired genital tract sepsis?', 'Group A β-haemolytic streptococcus (Streptococcus pyogenes).', 2),
(19, 'Causes', 'Name four indirect causes of maternal death.', 'Cardiac disease, anaemia, malaria and HIV (also epilepsy, asthma and diabetes).', 2),
(20, 'Three delays', 'What are the three delays?', 'Delay in deciding to seek care, delay in reaching the health facility, and delay in receiving adequate care.', 1),
(21, 'Three delays', "A woman waits for her husband's permission to go to hospital. Which delay is this?", 'The first delay: deciding to seek care.', 2),
(22, 'Three delays', 'A woman reaches the hospital but there is no blood or operating theatre. Which delay is this?', 'The third delay: receiving adequate care.', 2),
(23, 'Three delays', 'How long does untreated postpartum haemorrhage take to cause death?', 'About 2 hours (sepsis takes about 6 days).', 3),
(24, 'Prevention', 'What is the difference between basic and comprehensive EmONC?', 'Comprehensive EmONC adds caesarean section and blood transfusion.', 2),
(25, 'Prevention', 'What are the key interventions that reduce maternal deaths?', 'Family planning, antenatal care, a skilled birth attendant, EmONC, post-abortion care, postnatal care and MDSR.', 2),
(26, 'Prevention', 'What is MDSR?', 'Maternal Death Surveillance and Response: every death is notified, reviewed without blame, and the findings are acted upon.', 2),
(27, 'Red flags', 'Which red-flag symptoms need urgent review in a pregnant or postnatal woman?', 'Signs of sepsis, breathlessness and severe headache.', 1),
]}
QS = {
'np-1': dict(d=1, stem='A para 2 woman is seen on day 7 after a normal vaginal delivery. She is well and breastfeeding, and her lochia is pink-brown and not offensive.', q='Where is the fundus expected to be felt?', why='The fundus is at the umbilicus after delivery and falls by about 1 cm a day, so by day 7 it is about halfway down. It is not palpable by day 10–14.'),
'np-2': dict(d=2, stem='A para 3 woman is seen on day 16 after a home delivery. Her lochia has become bright red again and the uterus is still palpable three finger breadths above the symphysis. Her temperature is 37.2 °C.', why='A uterus that is still palpable after day 14 with a return of red lochia suggests retained tissue and subinvolution; ultrasound is used to look for it.'),
'np-3': dict(d=2, stem='A para 1 woman is seen on day 2 after a normal delivery. She feels well; her temperature is 37.1 °C and her pulse 82/min. A routine blood count shows a white cell count of 19 × 10⁹/L with a normal haemoglobin.', why='A white cell count of up to 20–25 × 10⁹/L is normal in the first days after delivery. In a well, afebrile woman it does not indicate infection.'),
'np-4': dict(d=3, stem='A para 2 woman with moderate mitral stenosis is in labour at 38 weeks. She has been stable throughout pregnancy.', q='When is she at the greatest risk of pulmonary oedema?', why='Contraction of the uterus after delivery returns blood to the circulation (autotransfusion), which raises cardiac output at the time when the heart is least able to cope.'),
'np-5': dict(d=2, stem='A para 1 woman is reviewed 8 hours after a ventouse delivery under epidural analgesia. She has not passed urine. A tender suprapubic swelling is palpable and the fundus is displaced upwards and to the right.', why='A woman should pass urine within 6 hours of delivery. A full bladder after epidural analgesia and instrumental delivery indicates urinary retention, which requires catheterisation; it also prevents the uterus from contracting well.'),
'np-6': dict(d=2, stem='A para 2 woman with blood group O RhD-negative delivered a healthy baby today. The baby is O RhD-positive and the direct Coombs test is negative. She had no antibodies at booking.', why='A non-sensitised RhD-negative mother of an RhD-positive baby receives 500 IU of anti-D within 72 hours. The Kleihauer test shows whether a larger fetomaternal haemorrhage requires a larger dose.'),
'np-7': dict(d=2, stem='A para 1 woman is breastfeeding on day 1 after a normal delivery. Her booking rubella IgG was negative.', why='Non-immune mothers are vaccinated before discharge, and breastfeeding is not a contraindication. Because a live vaccine is avoided in pregnancy, she should avoid pregnancy for 1 month.'),
'np-8': dict(d=2, stem='A para 2 woman had gestational diabetes controlled by diet. She delivered a 3.8 kg baby at 39 weeks, and her capillary glucose is normal after delivery.', why='Testing at 6 weeks detects diabetes that has persisted after pregnancy. HbA1c soon after delivery is unreliable.'),
'np-9': dict(d=2, stem='A para 3 woman is HBsAg-positive. Her baby is born at term and is well. She wishes to breastfeed.', why='Hepatitis B is not a contraindication to breastfeeding once the baby has received the vaccine and HBIG.'),
'np-10': dict(d=3, stem='A para 2 woman on day 3 after delivery has had a cough for 6 weeks, and her sputum smear is positive for acid-fast bacilli. She has not yet started treatment.', why='A mother with untreated smear-positive tuberculosis starts treatment, wears a mask and expresses her milk; the baby receives isoniazid prophylaxis and BCG. Direct breastfeeding resumes once she is smear-negative.'),
'np-11': dict(d=3, why='Vomiting, jaundice and cataracts in a breastfed baby suggest galactosaemia, which is an absolute contraindication to breast milk.'),
'np-12': dict(d=2, stem='A para 3 woman delivered a stillborn baby at 38 weeks. She is normotensive and has no other illness. She asks for medication to suppress lactation.', why='A single dose of cabergoline is the drug of choice. Bromocriptine and high-dose oestrogen are no longer used because of the risks of stroke, myocardial infarction and VTE.'),
'np-13': dict(d=1, stem='A para 1 woman is seen on day 4 after delivery. Both breasts are hard, full and tender, and the baby has difficulty latching on. Her temperature is 37.9 °C and there is no area of redness.', why='Hardness of both breasts on days 3–5 with a low-grade fever is breast engorgement, which is relieved by emptying the breasts. Antibiotics are indicated for a red, wedge-shaped area with high fever.'),
'np-14': dict(d=2, stem='Three weeks after delivery, a para 2 woman has a painful, red, wedge-shaped area on the right breast, a temperature of 38.6 °C and generalised aches. No fluctuant lump is palpable.', why='Infective mastitis is usually caused by Staphylococcus aureus; flucloxacillin is given and continued breastfeeding helps to empty the breast. Tetracycline is avoided during breastfeeding.'),
'np-15': dict(d=2, stem='A para 1 woman has taken flucloxacillin for 5 days for a red, tender breast. She still has a fever of 38.8 °C and now has a tense, fluctuant, very tender lump in the upper outer quadrant.', why='A fluctuant mass with persistent fever is a breast abscess, and the pus must be drained. She may continue to feed from the other breast.'),
'np-16': dict(d=2, stem='A para 3 woman is exclusively breastfeeding 6 weeks after delivery. She asks for a contraceptive pill to start today.', why='Progestogen-only methods do not reduce milk production and are the first choice during breastfeeding. The combined pill is avoided until 6 months.'),
'ps-1': dict(d=2, stem='A para 2 woman has a single temperature of 38.2 °C on day 12 after a vaginal delivery. All earlier observations were normal.', why='Puerperal pyrexia is a temperature of 38 °C or more at any time in the first 14 days. Puerperal morbidity requires 38 °C or more on 2 of the first 10 days, excluding the first 24 hours.'),
'ps-2': dict(d=1, stem='A para 1 woman is seen on day 3 after a caesarean section for prolonged labour with membranes ruptured for 30 hours. Her temperature is 38.6 °C and pulse 110/min. The lochia is offensive and the uterus is bulky and tender. The wound is clean and the breasts are soft.', why='Fever with offensive lochia and a tender, bulky uterus indicates endometritis, the commonest cause of puerperal fever.'),
'ps-3': dict(d=2, stem='A para 3 woman is seen on day 4 after a long labour with many vaginal examinations. She has fever and offensive lochia, and the uterus is tender. A high vaginal swab is sent.', why='Anaerobic streptococci, together with Bacteroides, are the classic commonest organisms in endometritis and cause the offensive odour. Staphylococcus aureus causes mastitis and wound infection.'),
'ps-4': dict(d=3, stem='A para 2 woman is seen on day 2 after a normal delivery. She has diarrhoea, vomiting and lower abdominal pain severe enough to require morphine, although the uterus is only mildly tender. Her temperature is 38.9 °C and pulse 132/min. Her son had a sore throat last week.', why='Pain out of proportion to the signs, diarrhoea and vomiting, and a family member with a sore throat suggest group A streptococcus, which is spread by the hands from the throat and causes rapidly fatal sepsis.'),
'ps-5': dict(d=3, stem='A para 1 woman is seen on day 3; her daughter has tonsillitis. She has severe abdominal pain requiring morphine, a red rash, a temperature of 39.2 °C and a blood pressure of 85/50 mmHg after fluids. IV piperacillin–tazobactam has been started.', why='Clindamycin suppresses streptococcal toxin production, so it is added in severe group A streptococcal sepsis. Gentamicin has no anaerobic cover.'),
'ps-6': dict(d=3, stem='A para 3 woman is confused on day 4 after a caesarean section. Her temperature is 35.4 °C, pulse 128/min, respiratory rate 26/min and blood pressure 95/60 mmHg.', why='A low temperature, tachycardia and tachypnoea with confusion indicate high-risk sepsis (obstetric qSOFA ≥ 2). A normal or low temperature does not exclude sepsis.'),
'ps-7': dict(d=2, stem='A para 2 woman has a fever of 38.7 °C, offensive lochia and a tender uterus on day 2 after an emergency caesarean section. She is breastfeeding. Cultures have been sent.', why='Endometritis is polymicrobial and requires IV broad-spectrum antibiotics that include anaerobic cover. Tetracycline and chloramphenicol are avoided during breastfeeding.'),
'ps-8': dict(d=3, stem='A para 4 woman on day 6 has received IV ceftriaxone and metronidazole for 3 days for postnatal uterine infection. She is still febrile. The uterus is bulky, the os admits one finger and the lochia is heavy.', why='Failure to respond within 48–72 hours requires a search for the cause; a bulky uterus with an open os suggests retained tissue, which is removed after antibiotics have been started.'),
'ps-9': dict(d=3, stem='A para 1 woman is seen on day 7 after a caesarean section. She has spiking fevers up to 39 °C despite 5 days of IV antibiotics, but between the spikes she appears well and eats. Pelvic ultrasound shows no collection or retained tissue. The malaria film and urine are negative.', why='A spiking fever despite antibiotics, with no collection, in a woman who appears well suggests pelvic (ovarian) vein thrombophlebitis, which responds to heparin.'),
'ps-10': dict(d=2, stem='A para 2 woman is seen on day 9 after a caesarean section. She has a swinging fever, diarrhoea and painful straining at stool. On rectal examination a tender, fluctuant mass is felt in front of the rectum.', why='A swinging fever, diarrhoea, tenesmus and a mass in the pouch of Douglas indicate a pelvic abscess. The pus must be drained under ultrasound guidance, by colpotomy or by laparotomy.'),
'ps-11': dict(d=3, stem='A para 3 woman is seen on day 4 after a caesarean section. She has severe wound pain that is far greater than the redness suggests. The skin around the wound is dusky and crepitus is felt. Her pulse is 125/min and blood pressure 90/55 mmHg.', why='Pain out of proportion to the signs, dusky skin and crepitus indicate necrotising fasciitis; early surgical debridement is life-saving.'),
'ps-12': dict(d=2, stem='A para 2 woman is about to have an emergency caesarean section. She has a history of anaphylaxis to penicillin.', why='Prophylaxis is given before the skin incision; in a woman with penicillin anaphylaxis, clindamycin replaces the cephalosporin. Co-amoxiclav is avoided before delivery because of necrotising enterocolitis.'),
'ps-13': dict(d=2, stem='A para 4 woman in Shendi is seen on day 5 after a normal delivery. She has rigors and a fever of 39.5 °C. The uterus is involuting and not tender, the lochia is normal, the breasts are soft, the chest is clear and the urine dipstick is normal.', why='In Sudan every postnatal fever requires a malaria film or rapid diagnostic test, especially when no pelvic source is found. The Widal test is unreliable; blood culture is used for typhoid.'),
'ps-14': dict(d=2, stem='A para 1 woman is seen on day 3 after a long labour during which she was catheterised. She has rigors, a temperature of 39 °C, right loin pain and dysuria. The uterus is not tender and the lochia is normal.', why='Loin pain and rigors after catheterisation suggest pyelonephritis, which requires IV treatment. Oral cefalexin is used for simple cystitis.'),
'ps-15': dict(d=2, stem='A para 2 woman was admitted on day 3 with fever, offensive lochia and a tender uterus, and was started on IV ceftriaxone and metronidazole. She has been afebrile for 48 hours, the uterus is no longer tender and she is eating well.', why='IV antibiotics are continued until the woman has been afebrile for 48 hours; after uncomplicated endometritis an oral course gives no additional benefit.'),
'ps-16': dict(d=2, stem='A para 3 woman presents to a rural health centre on day 3 after a home delivery. Her temperature is 39 °C and pulse 124/min; she has offensive lochia and a tender uterus. The nearest hospital is 2 hours away.', why='Each hour of delay in giving antibiotics increases the risk of death. A septic mother receives IV antibiotics and fluids before transfer, and is never sent home on oral drugs alone.'),
'pmd-1': dict(d=1, stem='A para 1 woman is seen on day 4 after a normal delivery. She cries easily, feels irritable and anxious, and is not sleeping well. She is feeding and caring for her baby well and has no thoughts of harm.', why='Tearfulness in the first days in a mother who is coping fully is the baby blues, which affects up to 80% of mothers and resolves within 2 weeks. Antidepressants are not needed.'),
'pmd-2': dict(d=2, stem='A para 2 woman is seen 7 weeks after delivery. For the last month she has felt low for most of the day, takes no pleasure in anything, cannot sleep even when the baby sleeps, and says she is a bad mother. She has no delusions and knows that she is unwell. Her temperature and blood pressure are normal.', why='Low mood and anhedonia for more than 2 weeks, with guilt and poor bonding, indicate postnatal depression. The baby blues lasts less than 2 weeks; psychosis is characterised by delusions and loss of insight.'),
'pmd-3': dict(d=2, stem='A para 3 woman is breastfeeding 8 weeks after delivery. Her Edinburgh Postnatal Depression Scale score is 16, with a score of 0 on the self-harm question. Haemoglobin and TSH are normal. She has moderate depression.', why='Sertraline passes into breast milk in very small amounts and is the SSRI of choice; breastfeeding continues. Fluoxetine accumulates in the baby.'),
'pmd-4': dict(d=3, stem='At her 6-week postnatal visit a para 1 woman has an Edinburgh Postnatal Depression Scale score of 8. She scored 2 on the last question, stating that the thought of harming herself has occurred "sometimes".', why='Any score on the self-harm item requires assessment on the same day, whatever the total score.'),
'pmd-5': dict(d=2, stem='A para 1 woman is seen on day 6 after delivery. She has not slept for 3 nights, is restless and perplexed, and says that voices are telling her the baby is the devil. Her temperature is 37 °C, blood pressure 115/75 mmHg and urinalysis normal.', why='Delusions about the baby with loss of insight in the first 2 weeks constitute a psychiatric emergency, with a risk of suicide and infanticide. Organic causes have been excluded.'),
'pmd-6': dict(d=3, stem='A para 3 woman is seen on day 5 after a long labour with manual removal of the placenta. She is confused, agitated and disorientated in place. Her temperature is 39 °C, pulse 124/min and blood pressure 120/80 mmHg; the lochia is offensive.', why='Confusion with fever and offensive lochia is organic until proved otherwise; a septic screen and a malaria film are done first.'),
'pmd-7': dict(d=3, stem='A para 2 woman on day 8 after delivery has had a severe headache for 2 days and had a convulsion this morning. Her blood pressure is 120/75 mmHg, there is no proteinuria and her temperature is normal.', why='Headache and convulsions in the first or second week with a normal blood pressure suggest cerebral venous thrombosis, which is best demonstrated by MR venography.'),
'pmd-8': dict(d=3, stem='Five months after delivery a para 1 woman is tired, low in mood, intolerant of cold and has gained weight. In the second month she had palpitations and lost weight. She is not anaemic.', why='A hyperthyroid phase followed by a hypothyroid phase at 4–8 months indicates postpartum thyroiditis, which mimics depression.'),
'pmd-9': dict(d=2, stem='A para 2 woman with bipolar disorder became elated, sleepless and deluded on day 5 after delivery. The psychiatrist has started lithium. She wishes to breastfeed.', why='Lithium reaches high levels in breast milk and can be toxic to the baby, so breastfeeding is avoided. Antipsychotic drugs usually allow breastfeeding.'),
'pmd-10': dict(d=3, stem='A para 1 woman with bipolar disorder is 34 weeks pregnant. After her first delivery she had a psychotic episode on day 4. She is currently well and not taking medication.', why='With bipolar disorder and a previous puerperal psychosis, her risk is about 60%; prophylaxis starts immediately after delivery, with daily review for the first 2 weeks.'),
'pmd-11': dict(d=2, stem='A para 2 woman had postnatal depression after her first delivery, treated with sertraline. She is now 12 weeks pregnant and asks about the chance of recurrence after this delivery.', why='Postnatal depression recurs in about 1 in 4 women after the next delivery. About 50% is the figure for puerperal psychosis.'),
'pmd-12': dict(d=3, stem='A para 3 woman began hearing voices and became agitated on day 7 after delivery and was admitted. Despite olanzapine she has refused all food and drink for 3 days and is not speaking.', why='Electroconvulsive therapy (ECT) acts rapidly and is safe in the puerperium; it is used when the illness is life-threatening, as in refusal of food and drink.'),
'pmd-13': dict(d=2, stem='A para 2 woman is breastfeeding 2 weeks after delivery. She has moderate depression and needs an antidepressant.', why='Fluoxetine has a long half-life and accumulates in the newborn. Sertraline and paroxetine reach very low levels in breast milk.'),
'pmd-14': dict(d=2, stem='A 27-year-old woman with bipolar disorder, well controlled on sodium valproate, wishes to conceive.', why='Valproate causes neural tube defects and reduced IQ, so it is changed before pregnancy. Stopping all treatment carries a risk of relapse.'),
'pmd-15': dict(d=2, stem='A para 1 woman became tearful from day 4 after delivery. She is now 4 weeks postpartum, still cries on most days and has lost interest in her baby.', why='Symptoms that last longer than 2 weeks are no longer the baby blues; prolonged or severe blues is a risk factor for depression and requires screening.'),
'mm-1': dict(d=1, why='Death from a pre-existing disease that is made worse by pregnancy is an indirect maternal death.'),
'mm-2': dict(d=2, why='A death from a direct or indirect cause between 42 days and 1 year after the end of pregnancy is a late maternal death.'),
'mm-3': dict(d=2, why='Accidental and incidental deaths are not maternal deaths and are not counted in the maternal mortality ratio, although they are pregnancy-related deaths.'),
'mm-4': dict(d=2, stem='A para 1 woman dies of pulmonary embolism on day 10 after an emergency caesarean section.', why='Venous thromboembolism is an obstetric complication of the puerperium, so the death is direct; any death within 42 days from such a cause is counted.'),
'mm-5': dict(d=2, why='Maternal mortality ratio = maternal deaths ÷ live births × 100 000 = 40 ÷ 16 000 × 100 000 = 250. Deaths per number of women aged 15–49 is the maternal mortality rate.'),
'mm-6': dict(d=1, stem='A para 3 woman had eclampsia at 36 weeks, followed by a massive PPH that required an emergency hysterectomy and intensive care. She went home well on day 12.', why='A woman who nearly died from a life-threatening complication but survived is a maternal near miss; such cases are reviewed to improve care.'),
'mm-7': dict(d=1, why='Sepsis is the leading cause of maternal death in Sudan, ahead of haemorrhage. Worldwide, haemorrhage is the leading cause.'),
'mm-8': dict(d=2, stem='A para 5 woman in a village bled heavily after a home delivery. Her mother-in-law considered the bleeding normal, and the family waited for her husband to return from the farm before leaving. She died on arrival at the hospital.', why='Failure to recognise danger and waiting for permission constitute the first delay: the decision to seek care.'),
'mm-9': dict(d=3, stem='A para 4 woman lives 80 km from the nearest hospital, and the road is cut off in the rainy season. In her last pregnancy she nearly died of haemorrhage on the way.', q='Which intervention best addresses her main delay?', why='Maternity waiting homes address the second delay, reaching care, by bringing the woman close to the hospital before labour.'),
'mm-10': dict(d=2, stem='A para 2 woman reaches a referral hospital 1 hour after a PPH. She waits 3 hours for blood because the blood bank has none, and dies.', why='Once the woman has reached the facility, a lack of blood, staff or an operating theatre is the third delay: receiving adequate care.'),
'mm-11': dict(d=3, q='Which complication, if untreated, causes death in the shortest time?', why='Untreated PPH causes death in about 2 hours, compared with about 1 day for uterine rupture, 2 days for eclampsia, 3 days for obstructed labour and 6 days for sepsis.'),
'mm-12': dict(d=2, why='These are the seven signal functions of basic EmONC; comprehensive care adds caesarean section and blood transfusion.'),
'mm-13': dict(d=2, why='The sisterhood method asks adults about deaths among their sisters; it is useful where vital registration is poor.'),
'mm-14': dict(d=3, why='In the United Kingdom VTE is the leading direct cause and cardiac disease the leading cause overall. Worldwide haemorrhage leads (about 27%); in Sudan sepsis leads.'),
'mm-15': dict(d=2, stem='A para 3 woman delivered a healthy baby in a health centre 6 hours ago and is ready to return to her village.', why='Most maternal deaths occur in the first days after delivery, so the early checks (day 3 and week 1–2) are the most important, with the final check at 6 weeks.'),
'ps-emq1#0': dict(d=2, why='Fever on days 0–2 after general anaesthesia with chest signs arises from the lungs.'),
'ps-emq1#1': dict(d=1, why='Hardness of both breasts on days 3–5 with a low-grade fever is engorgement, not infection.'),
'ps-emq1#2': dict(d=2, why='A low-grade fever with a tender, swollen calf in weeks 1–3 indicates deep vein thrombosis, which is confirmed by Doppler ultrasound.'),
'ps-emq1#3': dict(d=1, why='A red, hot, discharging wound on days 4–8 is a wound infection; it is opened and the pus is drained.'),
'pmd-emq2#0': dict(d=3, why='Failure of lactation, amenorrhoea and a low blood pressure after a massive PPH indicate pituitary necrosis.'),
'pmd-emq2#1': dict(d=2, why='Mania with delusions and a family history of bipolar disorder in the first 2 weeks indicates puerperal psychosis.'),
'pmd-emq2#2': dict(d=2, why='Convulsions with a high blood pressure and proteinuria after delivery indicate eclampsia; pre-eclampsia can begin up to 6 weeks postpartum.'),
'pmd-emq2#3': dict(d=3, why='Tiredness and low mood with a haemoglobin below 7 g/dL after a PPH indicate anaemia, which is treated before depression is diagnosed.'),
'np-emq3#0': dict(d=1, why='No menstruation, full breastfeeding and a baby under 6 months give 98% protection.'),
'np-emq3#1': dict(d=2, why='In a woman who is not breastfeeding and has no risk of VTE, the combined pill can be started from day 21.'),
'np-emq3#2': dict(d=3, why='Between 48 hours and 4 weeks the soft uterus carries a high risk of expulsion and perforation.'),
'np-emq3#3': dict(d=2, why='Puerperal mini-laparotomy within 7 days is convenient; otherwise interval sterilisation is performed after 6 weeks.'),
}
